INSERT INTO kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, prerequisite_concepts, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, skills_assessed, source, year, exam_body, related_question_ids, stem, options, correct_option, explanation, lifecycle_state, empirical_stats) VALUES
('use_of_english_0226', 'Use of English', 'Comprehension', 'Comprehension and Summary', NULL, '[{"weight": 1, "conceptId": "3r5lb7"}]'::jsonb, '{}', 3, 'application', 60, 'high', 'none', '[{"option": "A", "explanation": "Not supported — the passage attributes resistance to specific fears, not a lack of understanding.", "misconceptionId": "guessed_no_reasoning"}, {"option": "C", "explanation": "This is literally the fear the passage explicitly rebuts (''there is nothing... to suggest deregulation will cause the government to be indifferent''), not the writer''s own conclusion.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "This is also presented as one of the rebutted fears, not the writer''s actual suggestion.", "misconceptionId": "misunderstood_terminology"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'Those who have been following the argument for and against the deregulation of the oil industry in Nigeria may have got the impression that deregulation connotes lack of control or indifference on the part of the government. But there is nothing so far from official quarters to suggest that deregulation will cause the government to relinquish its control of the oil industry because the absence of direct control does not mean that it will surrender all its rights to the entrepreneurs who may want to participate in the industry. Yet the opposition expressed so far against stems from the fear that the government would leave Nigerians at the mercy of a heartless cartel who would command the heights of the oil industry and cause pump price of fuel to rise above the means of most Nigerians.

`As a result of such fears, many Nigerians have become resentful of deregulation and in fact the Nigeria Labour Congress  (NLC) has threatened to ‘deregulate’ the government if it should go ahead with the deregulation plan. But Nigerians have not fared any better with the economy totally in government control. Until recently, the most important sectors of the economy were in the hands of the government. Today, the deregulation of some of these sectors has broken its monopoly and introduced healthy competition to make a little easier for Nigerians. A good example is the breaking of the stifling monopoly of Nigeria Airways. Today, the traveller is king at the domestic airports as opposed to the struggle that air travels used to be under Nigeria Airways monopoly. Before, it was almost easier for a camel to pass through the eye of a needle than for travellers to board a plane.

Following from this, the apostles of deregulation rightly heap all the blame for the problems associated with petroleum products distribution in this country squarely on the government, which owns all the refineries and which sells fuel to local consumers through its agency, the Nigerian National Petroleum Corporation (NNPC). In the same way, the government argues that if the current NNPC monopoly were broken with the introduction of entrepreneurs to the refining and sale of petroleum products in the country, the Nigerian people would be all the better for it. It stands to reason that once the government continues to fix maximum prices would be all the better for it. It stands to reason that once the government continues to fix maximum prices for petroleum products in this country, the deregulation of the oil sector should bring some relief to the people by ensuring that wastage, corruption and inefficiency are reduced to the minimum. Consumers will also have the last laugh because competition will result in the availability of the products at reasonable prices. This appears to be the sense in deregulation.

The writer seems to suggest that', '[{"label": "A", "text": "nigerians do not understand the sense in deregulation", "isCorrect": false}, {"label": "B", "text": "deregulation, if properly implemented, will ultimately benefit ordinary nigerians through competition", "isCorrect": true}, {"label": "C", "text": "a deregulation economy will cause the government to be indifferent to the plight of ordinary nigerians", "isCorrect": false}, {"label": "D", "text": "only a heartless cartel will benefit by the deregulation of the oil industry", "isCorrect": false}]'::jsonb, 'B', 'The passage''s overall tone is cautiously pro-deregulation, arguing that competition will reduce wastage/corruption and benefit consumers — consistent only with option B.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('use_of_english_0227', 'Use of English', 'Synonyms/antonyms', 'Antonyms', NULL, '[{"weight": 1, "conceptId": "v4agon"}]'::jsonb, '{}', 2, 'recall', 60, 'low', 'none', '[{"option": "A", "explanation": "''Indubitable'' (as intended, despite the typo) is a synonym of incontrovertible — beyond doubt — not its opposite.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "''Practicable'' is about feasibility, an unrelated dimension to certainty of evidence.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "''Logical'' is about the validity of reasoning, not the certainty of the evidence itself.", "misconceptionId": "guessed_no_reasoning"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'Choose the option opposite in meaning to the underlined word(s).

The evidence the leader gave was

incontrovertible

.', '[{"label": "A", "text": "indulbitable", "isCorrect": false}, {"label": "B", "text": "disputable", "isCorrect": true}, {"label": "C", "text": "practicable", "isCorrect": false}, {"label": "D", "text": "logical", "isCorrect": false}]'::jsonb, 'B', '''Incontrovertible'' means beyond dispute/certain; its opposite is ''disputable'' (open to question).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('use_of_english_0228', 'Use of English', 'Grammatical usage', 'Concord (Subject-Verb Agreement)', NULL, '[{"weight": 1, "conceptId": "59ii9v"}]'::jsonb, '{}', 2, 'application', 60, 'low', 'none', '[{"option": "A", "explanation": "Uses singular ''does'' with a plural subject, and the wrong verb form ''covered'' after ''not''.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Uses singular ''does'' which does not agree with the plural subject ''operations''.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "Uses the wrong tense ''did'' and the wrong verb form ''covered'', both inconsistent with the present-tense context.", "misconceptionId": "misunderstood_terminology"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'Fill each gap with the most appropriate option from the lists provided.

The operations of the bank ........ not ...... cottage and small-scale industries?', '[{"label": "A", "text": "does / covered", "isCorrect": false}, {"label": "B", "text": "does / cover", "isCorrect": false}, {"label": "C", "text": "did / covered", "isCorrect": false}, {"label": "D", "text": "do / cover", "isCorrect": true}]'::jsonb, 'D', '''The operations'' is a plural subject, so it needs the plural auxiliary ''do'', not ''does'' or ''did'': ''do not cover''.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('use_of_english_0229', 'Use of English', 'Grammatical usage', 'Conditionals', NULL, '[{"weight": 1, "conceptId": "fbl55l"}]'::jsonb, '{}', 3, 'application', 60, 'low', 'none', '[{"option": "A", "explanation": "''In spite'' is grammatically incomplete (needs ''of'') and expresses concession, not condition.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "''Given'' implies assuming problems exist, the wrong nuance for ''I shall still travel as planned''.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "''In case of'' implies preparing for a contingency, not the intended ''if none arise'' meaning.", "misconceptionId": "overgeneralized_rule"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'Fill each gap with the most appropriate option from the lists provided.

....... any problems, I shall travel to London tomorrow on a business trip?', '[{"label": "A", "text": "in spite", "isCorrect": false}, {"label": "B", "text": "given", "isCorrect": false}, {"label": "C", "text": "in case of", "isCorrect": false}, {"label": "D", "text": "barring", "isCorrect": true}]'::jsonb, 'D', '''Barring any problems'' means ''if no problems arise'', which fits ''I shall travel tomorrow'' as the plan assuming nothing goes wrong.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('use_of_english_0230', 'Use of English', 'Idiomatic expressions', 'Sentence Interpretation (Idiom)', NULL, '[{"weight": 1, "conceptId": "91ez3x"}]'::jsonb, '{}', 2, 'recall', 60, 'low', 'none', '[{"option": "B", "explanation": "Wrongly assumes the change must be negative, when flux is neutral about direction.", "misconceptionId": "overgeneralized_rule"}, {"option": "C", "explanation": "Wrongly assumes the change must be positive, again missing flux''s neutral meaning.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "''Moribund'' means dying/stagnant, essentially the opposite of active flux/change.", "misconceptionId": "misunderstood_terminology"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'Select the option that best explain the information conveyed in the sentence.

The organization is constantly in a state of flux?', '[{"label": "A", "text": "The organization is constantly/continuously changing", "isCorrect": true}, {"label": "B", "text": "The organization is facing a difficult period", "isCorrect": false}, {"label": "C", "text": "The organization is experiencing good times", "isCorrect": false}, {"label": "D", "text": "The organization is moribund", "isCorrect": false}]'::jsonb, 'A', '''In a state of flux'' means undergoing continuous change (which could be positive or negative) — not specifically bad or good times, and not stagnation.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('use_of_english_0231', 'Use of English', 'Sentence completion', 'Contextual Word Pairs', NULL, '[{"weight": 1, "conceptId": "ak1vrj"}]'::jsonb, '{}', 2, 'application', 60, 'low', 'none', '[{"option": "A", "explanation": "''Okay'' and ''optimistic'' are both mildly positive, giving no real contrast for ''though'' to signal.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "''Nostalgic'' is about longing for the past, not a stance on the future, so it doesn''t fit logically.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "''Unsatisfied'' is not really a forward-looking stance on prospects, a weak fit for the sentence.", "misconceptionId": "guessed_no_reasoning"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'Fill each gap with the most appropriate option from the lists provided.

The future of the company is ...... though many seem .....about it?', '[{"label": "A", "text": "okay / optimistic", "isCorrect": false}, {"label": "B", "text": "promising / nostalgic", "isCorrect": false}, {"label": "C", "text": "bright / pessimistic", "isCorrect": true}, {"label": "D", "text": "dicy / unsatisfied", "isCorrect": false}]'::jsonb, 'C', '''Though'' signals a contrast: the future looks good (''bright'') even though many people''s feelings about it are negative (''pessimistic'') — the only pairing with genuine opposite valence.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('use_of_english_0232', 'Use of English', 'Comprehension', 'Comprehension and Summary', NULL, '[{"weight": 1, "conceptId": "3r5lb7"}]'::jsonb, '{}', 2, 'application', 60, 'high', 'none', '[{"option": "A", "explanation": "Too narrow — captures only the pro-deregulation side, ignoring the fears and counterarguments the passage also discusses.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "The opposite emphasis — the passage''s overall tone favours deregulation rather than warning against it.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Too narrow — the NNPC is only one specific example within the broader debate.", "misconceptionId": "overgeneralized_rule"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'Those who have been following the argument for and against the deregulation of the oil industry in Nigeria may have got the impression that deregulation connotes lack of control or indifference on the part of the government. But there is nothing so far from official quarters to suggest that deregulation will cause the government to relinquish its control of the oil industry because the absence of direct control does not mean that it will surrender all its rights to the entrepreneurs who may want to participate in the industry. Yet the opposition expressed so far against stems from the fear that the government would leave Nigerians at the mercy of a heartless cartel who would command the heights of the oil industry and cause pump price of fuel to rise above the means of most Nigerians.

`As a result of such fears, many Nigerians have become resentful of deregulation and in fact the Nigeria Labour Congress  (NLC) has threatened to ‘deregulate’ the government if it should go ahead with the deregulation plan. But Nigerians have not fared any better with the economy totally in government control. Until recently, the most important sectors of the economy were in the hands of the government. Today, the deregulation of some of these sectors has broken its monopoly and introduced healthy competition to make a little easier for Nigerians. A good example is the breaking of the stifling monopoly of Nigeria Airways. Today, the traveller is king at the domestic airports as opposed to the struggle that air travels used to be under Nigeria Airways monopoly. Before, it was almost easier for a camel to pass through the eye of a needle than for travellers to board a plane.

Following from this, the apostles of deregulation rightly heap all the blame for the problems associated with petroleum products distribution in this country squarely on the government, which owns all the refineries and which sells fuel to local consumers through its agency, the Nigerian National Petroleum Corporation (NNPC). In the same way, the government argues that if the current NNPC monopoly were broken with the introduction of entrepreneurs to the refining and sale of petroleum products in the country, the Nigerian people would be all the better for it. It stands to reason that once the government continues to fix maximum prices would be all the better for it. It stands to reason that once the government continues to fix maximum prices for petroleum products in this country, the deregulation of the oil sector should bring some relief to the people by ensuring that wastage, corruption and inefficiency are reduced to the minimum. Consumers will also have the last laugh because competition will result in the availability of the products at reasonable prices. This appears to be the sense in deregulation.

An appropriate title for this passage is', '[{"label": "A", "text": "the advantage of a deregulated economy", "isCorrect": false}, {"label": "B", "text": "the debate over deregulation of the oil industry", "isCorrect": true}, {"label": "C", "text": "highlighting the dangers of deregulation", "isCorrect": false}, {"label": "D", "text": "the problems of the NNPC", "isCorrect": false}]'::jsonb, 'B', 'The passage presents both the fears against deregulation and the arguments for it before reaching a qualified conclusion — a title should reflect that balanced debate, not just one side.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('use_of_english_0233', 'Use of English', 'Stress', 'Emphatic Stress', NULL, '[{"weight": 1, "conceptId": "odd0o9"}]'::jsonb, '{}', 2, 'application', 60, 'low', 'none', '[{"option": "A", "explanation": "Queries the object via a relative clause instead of the emphasized verb.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Queries the subject (''who'') rather than the emphasized verb.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Queries the object (''what'') rather than the emphasized verb.", "misconceptionId": "overgeneralized_rule"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'The word in capital letters has the emphatic stress. Choose the option that best fits the expression in the sentence.

The man BOUGHT the newspaper.', '[{"label": "A", "text": "Is this the newspaper which the man bought?", "isCorrect": false}, {"label": "B", "text": "Did the man buy the newspaper?", "isCorrect": true}, {"label": "C", "text": "Who bought the newspaper?", "isCorrect": false}, {"label": "D", "text": "What did the man buy?", "isCorrect": false}]'::jsonb, 'B', 'The stress on BOUGHT signals the verb is being contrasted/confirmed, so the matching question should query the verb while keeping subject (''the man'') and object (''the newspaper'') unchanged.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('use_of_english_0234', 'Use of English', 'Idiomatic expressions', 'Figures of Speech', NULL, '[{"weight": 1, "conceptId": "lwt4xp"}]'::jsonb, '{}', 2, 'recall', 60, 'low', 'none', '[{"option": "A", "explanation": "''Worth'' relates to general value, not the specific idiom about showing courage/character.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "''Position'' refers to role/rank, unrelated to demonstrating courage.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "''Skill'' is close but ''mettle'' specifically means courage/spirit under pressure, not competence.", "misconceptionId": "overgeneralized_rule"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'Fill each gap with the most appropriate option from the lists provided.

The match gave the team a chance to show their ........?', '[{"label": "A", "text": "worth", "isCorrect": false}, {"label": "B", "text": "position", "isCorrect": false}, {"label": "C", "text": "skill", "isCorrect": false}, {"label": "D", "text": "mettle", "isCorrect": true}]'::jsonb, 'D', '''To show one''s mettle'' is a fixed idiom meaning to demonstrate courage and character under pressure — exactly what a competitive match provides an opportunity to do.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('use_of_english_0235', 'Use of English', 'Comprehension', 'Cloze/Gap-fill in Context', NULL, '[{"weight": 1, "conceptId": "hbrpoi"}]'::jsonb, '{}', 2, 'application', 60, 'high', 'none', '[{"option": "A", "explanation": "''Deduction'' describes a type of reasoning, not the outcome of a well-tested hypothesis.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "''Notion'' is far too vague/informal for a scientifically validated hypothesis.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "''Thesis'' repeats an earlier stage of the passage''s own sequence (hypothesis→thesis-like idea) rather than the final validated status.", "misconceptionId": "overgeneralized_rule"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'The passage below has gaps numbered 11 to 20. Immediately following each gap, four options are provided. Choose the most appropriate option for each gap.

It is the business of the scientist to accumulate knowledge about the universe and all that is in it and to find if he is able, common

……11…..[A. experiment B. instruments C. approaches D. factors]

which underlie and account for the facts that he knows. He chooses when he can, the method of the controlled

…….12…..[A. respondent B. experiment C. system D. data]

. If he wants to find out the effect of light on growing plants, he takes many plants, as alike as possible. Some he stands in the sun, some in the shade, some in the dark, all the time keeping all other

.....13.....[A. studies B. procedures C. objects D. conditions]

(temperature, moisture, nourishments) the same. In this way, by keeping other variables

……..14……[A. constant B. good C. dark D. natural]

and by varying the light only, the effect of light on plants can be clearly seen. This

…….15…..[A. research B. method C. tool D. rationale]

of using ‘controls’ can be applied to a variety of situations and can be used to find the answers to questions as widely different as ‘must moisture be present if

…….16….[A. an alloy B. gold C. bar D. iron]

is to rust?’ and which variety of beans give the greatest yield in one

……17…..[A. climate B. period C. season D. weather]?

In the course of his

……18…..[A. finding B. queries C. experiment D. inquiries]

, the scientist may find what he thinks is one common explanation for an increasing number of facts the explanation, if it seems consistently to fit the various facts, is called

…….19……[A. an antithesis B. a principle C. a thesis D. a hypothesis]

. If this continues to stand the test of numerous experiments and remains unshaken, it becomes a

……20…..[A. deduction B. law C. notion D. thesis].

In question number 20 above, choose the best option from letters A-D that best completes the gap.', '[{"label": "A", "text": "deduction", "isCorrect": false}, {"label": "B", "text": "law", "isCorrect": true}, {"label": "C", "text": "notion", "isCorrect": false}, {"label": "D", "text": "thesis", "isCorrect": false}]'::jsonb, 'B', 'A hypothesis that survives repeated testing without being disproved becomes a scientific ''law''.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('use_of_english_0236', 'Use of English', 'Vowels', 'Vowel Sounds', NULL, '[{"weight": 1, "conceptId": "namskj"}]'::jsonb, '{}', 2, 'recall', 60, 'low', 'none', '[{"option": "A", "explanation": "''Does'' shares /ʌ/ with flood and son despite its different spelling.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "''Flood'' also shares /ʌ/ with the other two words.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "''Son'' shares /ʌ/ as well — all three are the same sound group.", "misconceptionId": "overgeneralized_rule"}]'::jsonb, '{}', 'jamb_past_question', 2002, 'JAMB', '{}', 'Choose the option that has a different vowel sound from the others?', '[{"label": "A", "text": "does", "isCorrect": false}, {"label": "B", "text": "flood", "isCorrect": false}, {"label": "C", "text": "goes", "isCorrect": true}, {"label": "D", "text": "son", "isCorrect": false}]'::jsonb, 'C', '''Does'', ''flood'' and ''son'' all share the short vowel sound /ʌ/. ''Goes'' has the different diphthong /əʊ/.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
